using System.ComponentModel;
using System.Text;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Logging;
using OpenAI;

// --- Configuration ---
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var modelId = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini-2024-07-18";

// --- DI setup ---
var services = new ServiceCollection();

services.AddLogging(b => b.AddConsole().SetMinimumLevel(LogLevel.Warning));

services.AddChatClient(b => b
    .UseOpenAIChatClient(modelId, new OpenAIClient(apiKey)));

var sp = services.BuildServiceProvider();
var chatClient = sp.GetRequiredService<IChatClient>();
var loggerFactory = sp.GetRequiredService<ILoggerFactory>();

// --- Tools ---
var notebook = new Notebook();

var tools = new AITool[]
{
    AIFunctionFactory.Create(
        ([Description("The search query to look up on the web")] string query) =>
        {
            return WebSearch.SearchAsync(query);
        },
        "web_search",
        "Searches the web for information on a topic and returns relevant snippets."),

    AIFunctionFactory.Create(
        (
            [Description("A short title for the note")] string title,
            [Description("The content to save")] string content
        ) =>
        {
            notebook.Add(title, content);
            return $"Note saved: \"{title}\"";
        },
        "save_note",
        "Saves a research note for later use in the summary. Use this to record key findings."),

    AIFunctionFactory.Create(
        () => notebook.GetAll(),
        "get_notes",
        "Retrieves all saved research notes to review before writing a summary."),
};

// --- Agent ---
var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research assistant. When given a topic:
        1. Use web_search to find information (make 2-3 searches with different queries).
        2. Use save_note to record each key finding with a descriptive title.
        3. Use get_notes to review all findings.
        4. Write a concise, well-structured summary of what you learned.
        Always cite your sources when possible.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking tools.",
    tools: tools,
    loggerFactory: loggerFactory);

// --- Main loop ---
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (type 'exit')      ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();

while (true)
{
    Console.Write("Topic> ");
    var topic = Console.ReadLine()?.Trim();

    if (string.IsNullOrEmpty(topic))
        continue;

    if (topic.Equals("exit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    Console.WriteLine();
    Console.WriteLine($"Researching: {topic}");
    Console.WriteLine(new string('─', 50));

    try
    {
        var session = await agent.CreateSessionAsync();

        var response = await agent.RunAsync(
            $"Research the following topic and provide a summary: {topic}",
            session,
            new ChatClientAgentRunOptions(new ChatOptions
            {
                Temperature = 0f,
                MaxOutputTokens = 2048,
            }));

        Console.WriteLine();
        Console.WriteLine(response.Text);
    }
    catch (Exception ex)
    {
        Console.WriteLine($"Error: {ex.Message}");
    }

    Console.WriteLine();
}

// --- Supporting types ---

/// <summary>Simple in-memory notebook for storing research notes.</summary>
sealed class Notebook
{
    private readonly List<(string Title, string Content)> _notes = [];

    public void Add(string title, string content) => _notes.Add((title, content));

    public void Clear() => _notes.Clear();

    public string GetAll()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        for (var i = 0; i < _notes.Count; i++)
        {
            sb.AppendLine($"[{i + 1}] {_notes[i].Title}");
            sb.AppendLine(_notes[i].Content);
            sb.AppendLine();
        }
        return sb.ToString();
    }
}

/// <summary>Simulated web search that returns plausible results.</summary>
static class WebSearch
{
    private static readonly HttpClient Http = new();

    /// <summary>
    /// Performs a web search. Uses a real search API if SEARCH_API_KEY is set,
    /// otherwise returns simulated results for demonstration.
    /// </summary>
    public static async Task<string> SearchAsync(string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        var searchApiKey = Environment.GetEnvironmentVariable("SEARCH_API_KEY");
        var searchEngineId = Environment.GetEnvironmentVariable("SEARCH_ENGINE_ID");

        if (!string.IsNullOrEmpty(searchApiKey) && !string.IsNullOrEmpty(searchEngineId))
        {
            return await LiveSearchAsync(query, searchApiKey, searchEngineId);
        }

